	"fmt"
	"os"
	"strconv"
)

const (
	MAX     = 100005
	MAX2    = 1000000000000000010 // 1e18 + 10
)

var (
	f0 = []byte("What are you doing at the end of the world? Are you busy? Will you save us?")
	s0 = []byte("What are you doing while sending \"")
	s1 = []byte("\"? Are you busy? Will you send \"")
	s2 = []byte("\"?")

	dp [MAX]int64
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	// Precompute dp
	dp[0] = int64(len(f0))
	for i := 1; i < MAX; i++ {
		if dp[i-1] > MAX2/2 {
			dp[i] = MAX2
		} else {
			dp[i] = dp[i-1]*2 + int64(len(s0)+len(s1)+len(s2))
		}
	}

	// Read N
	scanner.Scan()
	N, _ := strconv.Atoi(scanner.Text())

	var out strings.Builder

	for i := 0; i < N; i++ {
		scanner.Scan()
		n, _ := strconv.Atoi(scanner.Text())
		scanner.Scan()
		k, _ := strconv.ParseInt(scanner.Text(), 10, 64)
		k-- // 0-indexed

		c := solve(n, k)
		out.WriteByte(c)
	}

	fmt.Println(out.String())
}

func solve(n int, k int64) byte {
	for {
		if k >= dp[n] {
			return '.'
		}
		if n == 0 {
			return f0[k]
		}

		if k < int64(len(s0)) {
			return s0[k]
		}
		k -= int64(len(s0))

		if k < dp[n-1] {
			n--
			continue
		}
		k -= dp[n-1]

		if k < int64(len(s1)) {
			return s1[k]
		}
		k -= int64(len(s1))

		if k < dp[n-1] {
			n--
			continue
		}
		k -= dp[n-1]

		return s2[k]
	}
}

